import {MAX_SPC_SIZE} from './spc.mjs';
import {createSpcTemplate} from './spc-preview.mjs';
import {validateAirTimeline,summarizeAirCoordinates,unpackAirCoordinate} from './spc-air.mjs';
const node=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n};
const details=(title)=>{const d=node('details'),s=node('summary',title);d.append(s);return d};
export function createSpcSurface(root,catalog=null){const box=node('section');box.className='panel spc-panel';box.setAttribute('aria-labelledby','spc-title');const h=node('h2','打开谱面');h.id='spc-title';box.append(h);const intro=node('div');intro.className='spc-intro';for(const [icon,label] of [['♫','原版谱面'],['◉','本地解析'],['↗','无需登录']]){const chip=node('span');chip.className='spc-chip';const glyph=node('i',icon);glyph.setAttribute('aria-hidden','true');chip.append(glyph,node('span',label));intro.append(chip)}box.append(intro);const instructions=details('导入说明');instructions.append(node('p','SPC 最大 64 MiB，本地解析。每条最多 3000 音符、512 KiB（旧格式 128 KiB）；最多保存 400 条、20 MiB、300000 音符，超限不截断。'));box.append(instructions);const templateDetails=details('音符与轨道说明');createSpcTemplate(templateDetails);box.append(templateDetails);const select=node('select');select.setAttribute('aria-label','从曲目目录选择谱面');const manual=node('option','手动输入谱面路径');manual.value='';select.append(manual);const seed=node('input');seed.type='text';seed.maxLength=512;seed.placeholder='谱面路径（按原样使用）';seed.setAttribute('aria-label','自制谱面解码路径');const picker=node('input');picker.type='file';picker.accept='.spc,application/octet-stream';picker.setAttribute('aria-label','选择本地 SPC 文件');const status=node('p','选曲后选难度即可看谱。');status.setAttribute('role','status');status.setAttribute('aria-live','polite');const out=node('div');out.className='spc-report';const exp=node('button','导出 JSON');exp.setAttribute('aria-label','导出有界 SPC 报告 JSON');exp.type='button';exp.disabled=true;const clear=node('button','清除');clear.type='button';const custom=details('解析自制谱面');custom.append(node('p','选择自己的 SPC 文件，并填写制作时使用的谱面路径。文件只在本机解析。'),seed,picker);box.append(custom,status,out,exp,clear);let builtinController=null;let generation=0,worker=null,report=null,catalogValue=null,objectUrl=null,preview=null,activeTimeline=null,cloud=null,savedPreview=null;const downloadUrls=new Set();const selectedChart=()=>{if(!catalogValue||!select.value)return null;for(const song of catalogValue.songs)for(const chart of song.charts)if(chart.chartId===select.value)return chart;return null};function fillCatalog(c){catalogValue=c;}function dispose(){generation++;builtinController?.abort();builtinController=null;cloud?.invalidate();worker?.terminate();worker=null;if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}for(const url of downloadUrls){URL.revokeObjectURL(url);downloadUrls.delete(url)}report=null;activeTimeline=null;cloud?.setCanSave();preview?.dispose();preview=null;savedPreview?.dispose();savedPreview=null;out.replaceChildren();exp.disabled=true;picker.value='';}function fail(text){status.textContent=text;preview?.dispose();preview=null;out.replaceChildren();report=null;exp.disabled=true}function show(r,timeline){const airSummary=r.airSummary||(timeline.airVersion===1?summarizeAirCoordinates((timeline.airCoordinates||[]).map(unpackAirCoordinate)):null),unknownKeyPositionCount=Array.from(timeline.laneStart).filter((lane,i)=>lane<0&&timeline.kind[i]!==4).length;report=r;activeTimeline=timeline;cloud?.setCanSave();out.replaceChildren();const metrics=node('div');metrics.className='spc-metrics';const card=(icon,label,value)=>{const item=node('div');item.className='spc-metric';const glyph=node('i',icon);glyph.setAttribute('aria-hidden','true');item.append(glyph,node('span',label),node('strong',String(value)));metrics.append(item)};const source=node('span',r.builtin?'已打开原版谱面':r.cloudSaved?'已打开已保存的谱面':'已读取谱面');source.className='spc-source';metrics.append(source);card('♫','BPM',r.bpm.base);card('▤','音符',r.notes.count);card('◷','时长',r.time.startMs===null?'0':`${(r.time.spanMs/1000).toFixed(3)} 秒`);const unknownAirCount=airSummary?airSummary.unresolvedCount:Array.from(timeline.kind).filter(kind=>kind===4).length,unknownTotal=unknownKeyPositionCount+unknownAirCount;if(unknownTotal){const warning=node('span',`未知位置 ${unknownTotal}`);warning.className='spc-unknown-warning';warning.setAttribute('role','status');metrics.append(warning)}out.append(metrics);const technical=details('技术详情');out.append(technical);const addTechnical=(label,value)=>{const p=node('p');p.append(node('strong',label+'：'),document.createTextNode(String(value)));technical.append(p)};addTechnical('BPM 变化',r.bpm.changes.map(x=>`${x.timeMs} ms → ${x.bpm}`).join('；')||'无变化事件');addTechnical('原生类型计数',Object.entries(r.notes.kindCounts).sort((a,b)=>Number(a[0])-Number(b[0])).map(([k,v])=>`类型 ${k}：${v}`).join('；')||'0');addTechnical('音符时间范围',r.time.startMs===null?'无音符':`${r.time.startMs}–${r.time.endMs} ms（${(r.time.spanMs/1000).toFixed(3)} s）`);addTechnical('已知轨道覆盖（由原生类型映射推导）',`${r.tracks.items.join(', ')||'无'}${unknownKeyPositionCount?`；未知键轨位置 ${unknownKeyPositionCount}`:''}`);addTechnical('轨道判定',r.tracks.status);if(airSummary&&airSummary.unresolvedCount)addTechnical('未解析空轨坐标',`${airSummary.unresolvedCount}/${airSummary.count}（Catch ${airSummary.catchCount} · Flick ${airSummary.flickCount}）`);else if(!airSummary&&Array.from(timeline.kind).some(kind=>kind===4))addTechnical('未保存空轨坐标',Array.from(timeline.kind).filter(kind=>kind===4).length);status.textContent=r.builtin?'原版谱面已打开。':r.cloudSaved?'已打开已保存的谱面':'解析完成，可以查看谱面。';exp.disabled=Boolean(r.cloudSaved||r.builtin);void import('./spc-preview.mjs').then(({createSpcPreview,createTimelineIndex})=>{if(report===r){if(!timeline.index)timeline.index=createTimelineIndex(timeline);preview=createSpcPreview(out,r,timeline);if(r.cloudSaved)out.querySelector('.spc-preview h3')?.replaceChildren(node('span','已保存的解析时间线'))}}).catch(()=>{})}select.addEventListener('change',()=>{dispose();const chart=selectedChart();if(chart)seed.value=chart.spc?.lookupPath||`${chart.chartId}.spc`;status.textContent='谱面选择已更改；旧分析已清除。'});seed.addEventListener('input',()=>{select.value='';dispose();status.textContent='谱面路径已更改；旧分析已清除。'});picker.addEventListener('change',async()=>{const file=picker.files?.[0];dispose();const token=generation;if(!file){status.textContent='请选择 .spc 文件。';return}const chart=selectedChart(),lookupPath=chart?.spc?.lookupPath??seed.value;if(!lookupPath){fail('需要自制谱面解码路径；手动输入不做修剪或规范化。');return}const whitespace=/^[\s]|[\s]$/u.test(lookupPath);if(whitespace)status.textContent='警告：谱面路径含首尾空格，将按原样使用。';if(file.size>MAX_SPC_SIZE){fail('文件超过 64 MiB。');return}try{status.textContent=whitespace?'警告：谱面路径含首尾空格，按原样读取…':'正在读取谱面…';const bytes=await file.arrayBuffer();if(token!==generation)return;if(bytes.byteLength>MAX_SPC_SIZE){fail('读取结果超过 64 MiB。');return}const w=new Worker(new URL('./spc-worker.mjs',import.meta.url),{type:'module'});worker=w;w.onmessage=e=>{if(token!==generation||e.data?.token!==token)return;worker?.terminate();worker=null;if(e.data.status==='ok')show(e.data.report,e.data.timeline);else fail(`读取失败，请重试（${String(e.data.errorCode||'invalid')}）。`)};w.onerror=()=>{if(token===generation){worker?.terminate();worker=null;fail('SPC Worker 不可用，请重试。')}};w.onmessageerror=()=>{if(token===generation){worker?.terminate();worker=null;fail('SPC Worker 通信失败。')}};status.textContent='正在分析谱面…';w.postMessage({token,bytes,lookupPath,noteLimit:20},[bytes])}catch{if(token===generation)fail('本地读取或 Worker 启动失败。')}});clear.addEventListener('click',()=>{dispose();cloud?.clearImport();status.textContent='已清除本地 SPC 结果。'});exp.addEventListener('click',()=>{if(!report||report.builtin||report.cloudSaved)return;const blob=new Blob([JSON.stringify(report)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);downloadUrls.add(url);const a=node('a');a.href=url;a.download='in-falsus-spc-analysis.json';a.click();setTimeout(()=>{URL.revokeObjectURL(url);downloadUrls.delete(url)},10000)});addEventListener('pagehide',()=>{dispose();cloud?.clear()});addEventListener('pageshow',e=>{if(e.persisted){dispose();status.textContent='页面恢复后已清除本地 SPC 分析。'}});fillCatalog(catalog);root.append(box);void import('./spc-cloud.mjs').then(({createSpcCloud})=>{const mount=node('div');box.insertBefore(mount,clear);cloud=createSpcCloud(mount,{catalog:()=>catalogValue,saveCurrent(){if(!report||report.cloudSaved||report.builtin||!activeTimeline)return null;return {chartId:null,bpm:{base:report.bpm.base,changes:report.bpm.changes.map(x=>({timeMs:x.timeMs,bpm:x.bpm}))},timeline:{...Object.fromEntries(['startMs','endMs','kind','laneStart','laneEnd'].map(k=>[k,Array.from(activeTimeline[k])])),airVersion:1,airCoordinates:(activeTimeline.airCoordinates||[]).map(tuple=>[...tuple])}}},openSaved(p){dispose();openParsed(p,'private')},clearSaved(){if(report?.cloudSaved||savedPreview){dispose();status.textContent='私有登录已失效；已清除打开的私有时间线。'}}})}).catch(()=>{});function openParsed(p,source){const t=Object.fromEntries(['startMs','endMs','kind','laneStart','laneEnd'].map(k=>[k,Int32Array.from(p.timeline[k])]));const extension=validateAirTimeline(p.timeline);if(extension?.airVersion===1){t.airVersion=1;t.airCoordinates=extension.airCoordinates}const counts={};for(const k of t.kind)counts[k]=(counts[k]||0)+1;const min=t.startMs.length?Math.min(...t.startMs):null,max=t.endMs.length?Math.max(...t.endMs):null;const r={cloudSaved:source==='private',builtin:source==='builtin',bpm:p.bpm,notes:{count:t.kind.length,kindCounts:counts},airSummary:extension?.airVersion===1?summarizeAirCoordinates(extension.airCoordinates.map(unpackAirCoordinate)):null,tracks:{unknownPositionCount:Array.from(t.laneStart).filter((x,i)=>x<0&&t.kind[i]!==4).length,items:[...new Set(Array.from(t.laneStart).flatMap((x,i)=>x<0?[]:Array.from({length:t.laneEnd[i]-x+1},(_,j)=>x+j)))].sort((a,b)=>a-b),status:t.laneStart.some(x=>x<0)?'partial':'verified'},time:{startMs:min,endMs:max,spanMs:min===null?0:max-min}};show(r,t)}function openChart(chartId){const chart=(catalogValue?.songs||[]).flatMap(s=>s.charts||[]).find(c=>c.chartId===chartId&&c.available);if(!chart)return false;dispose();const token=generation;builtinController=new AbortController();status.textContent='正在打开原版谱面…';box.scrollIntoView?.({behavior:'smooth',block:'start'});void fetch('/api/builtin-charts/'+encodeURIComponent(chartId),{credentials:'omit',signal:builtinController.signal,cache:'no-cache'}).then(async response=>{if(!response.ok)throw Object.assign(Error('read'),{status:response.status});return response.json()}).then(data=>{if(token===generation)openParsed(data.payload,'builtin')}).catch(error=>{if(token!==generation||error.name==='AbortError')return;fail(error.status===404?'此谱面暂未收录到公开谱面库。':'谱面暂时无法打开，请稍后重试。')});return true;}return {setCatalog:fillCatalog,clear:dispose,openChart};}
